<script setup>import { ref, computed } from 'vue'; import { useRoute } from 'vue-router'; import { Volume2, Lightbulb, ArrowRight, RotateCcw } from 'lucide-vue-next'; const route=useRoute(); const selected=ref([]); const complete=ref(false); const letters=['D','A','B','D','P','D']; const toggle=(i,l)=>{if(l==='D'&&!selected.value.includes(i)) selected.value.push(i); if(selected.value.length===3) setTimeout(()=>complete.value=true,300)}; const title=computed(()=>route.params.slug.includes('trace')?'Trace the Letter D':'Find the Letter D')</script>
<template><div class="activity-page"><header><div><span>Letter D</span><h1>{{title}}</h1></div><div class="activity-progress"><span>Activity 3 of 4</span><div><i style="width:75%"></i></div></div></header><section v-if="!complete" class="activity-stage"><div class="instruction"><button><Volume2/></button><div><small>LISTEN</small><h2>Tap every uppercase D you can find.</h2></div><button class="hint"><Lightbulb/> Hint</button></div><div class="letter-board"><button v-for="(letter,index) in letters" :key="index" :class="{correct:selected.includes(index)}" @click="toggle(index,letter)">{{letter}}<span v-if="selected.includes(index)">✓</span></button></div><div class="encouragement">{{selected.length===0?'Take your time. Look carefully!':selected.length<3?'Great spotting! Keep going.':'Wonderful work!'}}</div></section><section v-else class="celebration"><div class="confetti">✦ ★ ✧ ★ ✦</div><span class="big-star">★</span><h1>You did it, Tunde!</h1><p>You found every Letter D.</p><div class="score-stars">★ ★ ★</div><div><button class="kid-button pale" @click="complete=false;selected=[]"><RotateCcw/> Play again</button><RouterLink class="kid-button green" to="/play/tunde/home">Next activity <ArrowRight/></RouterLink></div></section></div></template>
